import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BUwdTBzS.js";const b=JSON.parse('{"title":"6C 前后端联调详细流程","description":"","frontmatter":{"title":"6C 前后端联调详细流程"},"headers":[],"relativePath":"dev-flow/references/integration-flow.md","filePath":"dev-flow/references/integration-flow.md","lastUpdated":null}'),r={name:"dev-flow/references/integration-flow.md"};function c(l,t,i,n,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/integration-flow.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="_6c-前后端联调详细流程" tabindex="-1">6C 前后端联调详细流程 <a class="header-anchor" href="#_6c-前后端联调详细流程" aria-label="Permalink to &quot;6C 前后端联调详细流程&quot;">​</a></h1><blockquote><p>本文件由 flow.md 步骤 6C 按需加载。选择「🔗 进行联调」时加载联调执行流程；选择「📝 生成 Commit Message 并暂存」或「⏸️ 直接暂存」时加载暂存等待状态。</p></blockquote><h2 id="联调执行流程" tabindex="-1">联调执行流程 <a class="header-anchor" href="#联调执行流程" aria-label="Permalink to &quot;联调执行流程&quot;">​</a></h2><ol><li><strong>环境确认</strong>：确认后端接口已就绪、dev server 已启动、测试数据已准备</li><li><strong>恢复真实逻辑</strong>：如有灰度强制开启等调试代码，评估是否需要临时恢复真实逻辑进行联调（或保留调试代码辅助排查）</li><li><strong>功能验证</strong>：按需求逐项验证前后端交互是否正常</li></ol><ul><li>接口请求/响应数据格式是否匹配</li><li>业务逻辑是否符合预期（增删改查、状态流转等）</li><li>异常场景处理（接口超时、错误码、空数据等）</li></ul><ol><li><strong>问题记录</strong>：联调中发现的问题分类记录</li></ol><ul><li>前端问题 → 回退步骤 5 修复 → 重走 5.5 → 6A → 继续联调</li><li>后端问题 → 记录并反馈给后端，等待修复后重新验证</li><li>协议问题 → 前后端协商确认，更新工作上下文 <code>## 约束与决策</code></li></ul><h2 id="暂存等待状态" tabindex="-1">暂存等待状态 <a class="header-anchor" href="#暂存等待状态" aria-label="Permalink to &quot;暂存等待状态&quot;">​</a></h2><ul><li>更新工作上下文进度为「等待联调」，恢复指令中记录联调前置条件</li><li>恢复指令中标注暂存前置处理的执行情况（是否已生成 commit）</li><li>后端就绪后，用户通过迭代修复信号（如「后端接口好了」「可以联调了」「继续上次的需求」）恢复流程</li><li>恢复后从联调执行流程的第 1 步开始</li></ul><h2 id="v3-字段写入指引-联调场景-2026-05-12-新增" tabindex="-1">v3 字段写入指引（联调场景，2026-05-12 新增） <a class="header-anchor" href="#v3-字段写入指引-联调场景-2026-05-12-新增" aria-label="Permalink to &quot;v3 字段写入指引（联调场景，2026-05-12 新增）&quot;">​</a></h2><blockquote><p>本章节定义联调场景下 <code>.flow</code> 文件 v3 字段的写入规则，与 <code>references/active-flows.md</code> 的 v3 schema 联动。</p></blockquote><h3 id="进入联调时-步骤-6c-触发" tabindex="-1">进入联调时（步骤 6C 触发） <a class="header-anchor" href="#进入联调时-步骤-6c-触发" aria-label="Permalink to &quot;进入联调时（步骤 6C 触发）&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>.flow</code> 字段</th><th>写入值</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>integration</code></td><td>与 <code>current_step=6</code> 正交，标记当前处于联调阶段</td></tr><tr><td><code>status</code></td><td><code>active</code></td><td>用户主动联调推进时</td></tr><tr><td><code>recovery.yesterday</code></td><td>&quot;联调已开始，前端已恢复真实逻辑（或保留调试代码）&quot; 等</td><td>与工作上下文 <code>### 恢复指令</code> 同步</td></tr><tr><td><code>recovery.next_action</code></td><td>&quot;验证 X 接口的 Y 场景&quot; / &quot;等待后端修复 Z 问题&quot;</td><td>联调中的下一步具体动作</td></tr><tr><td><code>recovery.pending</code></td><td>联调发现的待确认问题（前后端协议不一致 / 异常场景未覆盖等）</td><td>0-3 条</td></tr></tbody></table><h3 id="暂存等待后端时-暂存等待状态触发" tabindex="-1">暂存等待后端时（暂存等待状态触发） <a class="header-anchor" href="#暂存等待后端时-暂存等待状态触发" aria-label="Permalink to &quot;暂存等待后端时（暂存等待状态触发）&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>.flow</code> 字段</th><th>写入值</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>integration</code>（保持不变）</td><td>阶段语义不变，仍属联调阶段</td></tr><tr><td><code>status</code></td><td><code>blocked-by-backend</code></td><td><strong>关键状态切换</strong>：从 <code>active</code> 切换到 <code>blocked-by-backend</code>，新对话恢复时 AI 首响欢迎语会变为「接口好了吗？还是先看看其他需求？」</td></tr><tr><td><code>recovery.yesterday</code></td><td>&quot;联调发现 X 接口 Y 字段缺失，已暂存等待后端&quot;</td><td>简述阻塞原因</td></tr><tr><td><code>recovery.next_action</code></td><td>&quot;等后端确认 X 接口修复进度后恢复联调&quot;</td><td>明确等待对象</td></tr><tr><td><code>recovery.pending</code></td><td>待后端确认/修复的具体问题清单</td><td>必填，作为后端就绪后的检查清单</td></tr></tbody></table><h3 id="联调恢复时-用户说「后端接口好了」等信号" tabindex="-1">联调恢复时（用户说「后端接口好了」等信号） <a class="header-anchor" href="#联调恢复时-用户说「后端接口好了」等信号" aria-label="Permalink to &quot;联调恢复时（用户说「后端接口好了」等信号）&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>.flow</code> 字段</th><th>写入值</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>integration</code>（保持不变）</td><td>—</td></tr><tr><td><code>status</code></td><td><code>active</code></td><td>从 <code>blocked-by-backend</code> 切回 <code>active</code></td></tr><tr><td><code>recovery.yesterday</code></td><td>&quot;暂存期间后端已修复 X，准备恢复联调&quot;</td><td>衔接暂存到恢复的过渡描述</td></tr><tr><td><code>recovery.next_action</code></td><td>&quot;重新验证 X 接口的 Y 场景&quot;</td><td>从联调执行流程第 1 步开始</td></tr></tbody></table><h3 id="联调通过时-进入步骤-7" tabindex="-1">联调通过时（进入步骤 7） <a class="header-anchor" href="#联调通过时-进入步骤-7" aria-label="Permalink to &quot;联调通过时（进入步骤 7）&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>.flow</code> 字段</th><th>写入值</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td>切换为 <code>commit-archive</code></td><td>阶段切换信号</td></tr><tr><td><code>status</code></td><td><code>active</code></td><td>—</td></tr><tr><td><code>last_commit_hash</code></td><td>步骤 7 commit 后的新 hash</td><td>见 <code>step-router.md</code> L482-484</td></tr></tbody></table><h3 id="联调专用工作上下文区块" tabindex="-1">联调专用工作上下文区块 <a class="header-anchor" href="#联调专用工作上下文区块" aria-label="Permalink to &quot;联调专用工作上下文区块&quot;">​</a></h3><p>进入 <code>phase: integration</code> 时，工作上下文必须存在 <code>## 联调暂存</code> 区块（见 <code>references/working-context.md</code> §「阶段感知区块」→ §「<code>## 联调暂存</code>（仅 <code>phase: integration</code> 时强制要求）」），用于记录&quot;为联调临时改动、联调结束后必须恢复&quot;的清单。 <strong>该区块在联调结束后不删除</strong>（作为历史档案），仅将每条记录的&quot;状态&quot;列改为 ✅ 已恢复 或 ❌ 已遗留。</p><h2 id="联调通过标准" tabindex="-1">联调通过标准 <a class="header-anchor" href="#联调通过标准" aria-label="Permalink to &quot;联调通过标准&quot;">​</a></h2><ul><li>所有涉及的接口调用正常（请求发出、响应正确解析）</li><li>业务功能符合需求描述（任务平台/Figma 中定义的行为）</li><li>无控制台报错（网络错误、JS 异常等）</li></ul><h2 id="回退机制" tabindex="-1">回退机制 <a class="header-anchor" href="#回退机制" aria-label="Permalink to &quot;回退机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>处理</th></tr></thead><tbody><tr><td>✅ 联调通过</td><td>清理调试代码 → 步骤 7</td></tr><tr><td>⚠️ 前端问题</td><td>回退步骤 5 修复 → 5.5 → 6A → 继续 6C 联调</td></tr><tr><td>⚠️ 后端问题</td><td>记录问题 → 暂存等待后端修复 → 后端修复后恢复联调</td></tr><tr><td>⚠️ 协议不一致</td><td>前后端协商 → 按协商结果调整（可能回退步骤 3 重新制定方案）</td></tr><tr><td>❌ 联调不通过</td><td>分析根因 → 按根因回退到对应步骤</td></tr></tbody></table>',26)])])}const q=e(r,[["render",c]]);export{b as __pageData,q as default};
